void Add(SiegeGeneratorSystemType t,string n,string r){systems.Add(new SiegeGeneratorSystemSlot{displayName=n,type=t,capability=n,role=r});}
public bool ValidateConnections(out string report){var e=new List<string>();if(request.mainMapCount!=5)e.Add("Exactly 5 main maps required.");if(request.subMapsPerMainMap!=7)e.Add("Exactly 7 sub-maps per main map required.");if(request.totalSubMaps!=35)e.Add("Exactly 35 sub-maps required.");if(request.capturePoints)e.Add("Capture points are disabled in Siege.");if(request.csRoundRules)e.Add("CS rules are disabled in Siege.");if(!request.requireControlCore)e.Add("Control Core is mandatory.");if(!request.finalRoundAtOneOne||!request.finalRoundSimultaneousAttackDefense)e.Add("1-1 simultaneous final round is mandatory.");foreach(var s in systems)if(s.required&&s.reference==null)e.Add("Missing: "+s.displayName);report=e.Count==0?"Siege connections valid.":string.Join("\n",e);return e.Count==0;}
public void GenerateFinalSiegeWorld(){if(!ValidateConnections(out var v)){lastGenerationReport=v;return;}if(generatedWorld==null)generatedWorld=ScriptableObject.CreateInstance<SiegeGeneratedWorldData>();generatedWorld.Clear();generatedWorld.worldName=request.worldName;generatedWorld.mainMaps=5;generatedWorld.subMapsPerMain=7;generatedWorld.totalSubMaps=35;string[] mains={"Ironwall Bastion","Fallen Citadel","Sunfire Fortress","Frostguard Stronghold","Abyssal Citadel"};string[] env={"Grasslands","Ruins","Desert","Snow","Ocean"};for(int m=0;m<5;m++)for(int s=0;s<7;s++){var map=new SiegeMapBuildData{mainMapIndex=m+1,subMapIndex=s+1,mainMapName=mains[m],subMapName=mains[m]+" — Siege Sector "+(s+1),environment=env[m],defensiveTheme="Fortified destructible stronghold",terrainBrief="Strategic invasion lanes, high ground, choke points and alternate routes.",infrastructureBrief="Walls, reinforced gates, towers, barricades, defensive buildings and protected Core chamber.",coreBrief="Mandatory Control Core deep inside defended territory.",destructionBrief="Designated walls, gates, buildings and barricades are destructible.",attackRouteBrief="Multiple viable invasion approaches.",defenseBrief="Layered defenses for delaying and stopping attackers."};generatedWorld.maps.Add(map);var c=new SiegeGenerationContext{generator=this,request=request,map=map,world=generatedWorld};foreach(var x in systems){if(!x.connected||!x.useDuringGeneration||x.reference==null)continue;var p=x.reference as ISiegeWorldGenerationProvider;if(p!=null&&p.CanGenerate(x.type))p.GenerateForSiege(c,request,out _);}}generatedWorld.readyForLobby=true;generatedWorld.readyForServer=true;generated=true;lastGenerationReport="Generated 35 Siege sub-maps with Siege-specific fortified infrastructure.";}
}}